inline std::optional<Rgba> over_premultiplied(const Rgba& src, const Rgba& dst) noexcept {
    if (!valid_premultiplied(src) || !valid_premultiplied(dst)) {
        return std::nullopt;
    }
    const double keep = 1.0 - src.a;
    Rgba out;
    out.r = src.r + dst.r * keep;
    out.g = src.g + dst.g * keep;
    out.b = src.b + dst.b * keep;
    out.a = src.a + dst.a * keep;
    return out;
}

inline std::optional<Rgba> over_straight(const Rgba& src, const Rgba& dst) noexcept {
    const std::optional<Rgba> premul_src = premultiply(src);
    if (!premul_src.has_value()) {
        return std::nullopt;
    }
    return over_premultiplied(*premul_src, dst);
}

bool begin_color_frame(const GlApi& gl, int width, int height,
                       const study_blend::Rgba& background) noexcept {
    if (width <= 0 || height <= 0 || !study_blend::valid_rgba(background)) return false;
    if (!check(gl, "frame entry")) return false;
    gl.Viewport(0, 0, width, height);
    if (!check(gl, "Viewport")) return false;
    gl.ClearColor(static_cast<GLfloat>(background.r), static_cast<GLfloat>(background.g),
                  static_cast<GLfloat>(background.b), static_cast<GLfloat>(background.a));
    if (!check(gl, "ClearColor")) return false;
    gl.Clear(ColorBufferBit);
    return check(gl, "Clear");
}

bool draw_triangles(const GlApi& gl, GLuint program, GLuint vao, GLsizei available,
                    GLint first, GLsizei count, int width, int height) noexcept {
    // Preserve the convenience wrapper's rejection-before-clear contract.
    if (!valid_range(available, first, count) || !program || !vao) return false;
    return begin_color_frame(gl, width, height, {0.05, 0.08, 0.12, 1.0}) &&
           submit_triangles(gl, program, vao, available, first, count);
}

inline bool configure(const study_gl::GlApi& gl, const Case& c) noexcept {
    using namespace study_gl;
    if (gl.GetError()) return false;
    gl.Disable(CullFaceCap);
    gl.Disable(FramebufferSrgb); // Numeric channel experiment, not sRGB encoding.
    gl.Disable(Dither);         // Make 8-bit readback comparison easier.
    gl.BlendEquation(FuncAdd);
    const GLenum rgb_source = c.premultiplied && !c.wrong_factor ? One : SrcAlpha;
    gl.BlendFuncSeparate(rgb_source, OneMinusSrcAlpha,
                         c.legacy_alpha ? SrcAlpha : One, OneMinusSrcAlpha);
    if (c.disabled) gl.Disable(Blend); else gl.Enable(Blend);
    return gl.GetError() == 0;
}

inline std::array<study_mesh::Vertex2,12> make_layers() noexcept {
    std::array<study_mesh::Vertex2,12> vertices{};
    const auto quad = study_quad::make_quad();
    for (std::size_t i=0; i<6; ++i) {
        vertices[i] = {quad[i].x - 0.25f, quad[i].y};
        vertices[i+6] = {quad[i].x + 0.25f, quad[i].y};
    }
    return vertices;
}

inline bool render(const study_gl::GlApi& gl, study_gl::GLuint program,
                   study_gl::GLuint vao, study_gl::GLsizei available,
                   const Case& c, int width, int height, double background_alpha=1.0) noexcept {
    // Validate the entire scene before clearing or submitting the first half.
    if (available != 12 || !program || !vao) return false;
    if (!study_gl::begin_color_frame(gl,width,height,{0,0,0,background_alpha})) return false;
    const int first = c.reverse ? 6 : 0;
    return study_gl::submit_triangles(gl,program,vao,available,first,6) &&
           study_gl::submit_triangles(gl,program,vao,available,6-first,6);
}
